const randomCode=()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789', bytes=crypto.getRandomValues(new Uint8Array(8));return [...bytes].map(b=>chars[b%chars.length]).join('')};
const hash=str=>{let h=2166136261;for(const ch of str){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
const pick=(array,seed)=>array[hash(String(seed))%array.length];
