const app={mode:'local',firebase:null,db:null,auth:null,api:null,uid:null,room:null,code:'',player:'khushi',persona:'khushi',loginTab:'create',joinCode:'',view:'lobby',sound:true,localChannel:null,unsub:null,writing:false,stroke:null,brush:'#db4a88',brushSize:5,eraser:false,canvasReady:false,connected:false,pending:false};
function roomKey(code){return 'usverse-room-'+code}
function roomScore(s){return s.scores[app.player]??0}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function sfx(pitch=550){if(!app.sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;const ctx=new Audio(), osc=ctx.createOscillator(),g=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(pitch,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(pitch*1.25,ctx.currentTime+.12);g.gain.setValueAtTime(.08,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.17);osc.connect(g);g.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.18);osc.onended=()=>ctx.close()}catch(e){}}
function confetti(){const c=$('#confetti');c.innerHTML='';const colors=['#ef87bf','#b995ff','#6de4e9','#ffe08d'];for(let i=0;i<70;i++){const el=document.createElement('i');el.className='confetto';el.style.left=Math.random()*100+'%';el.style.background=colors[i%colors.length];el.style.animationDelay=Math.random()*.75+'s';el.style.animationDuration=(2.2+Math.random()*2)+'s';c.appendChild(el)}setTimeout(()=>c.innerHTML='',4800);sfx(820)}
function log(s,msg){s.feed.unshift({text:msg,ts:now()});s.feed=s.feed.slice(0,16)}
function award(s,who,score=0,coins=0,msg=''){s.scores[who]=Math.max(0,(s.scores[who]||0)+score);s.coins[who]=Math.max(0,(s.coins[who]||0)+coins);if(msg)log(s,`${nice(who)} ${msg}`)}
function validState(){return app.room?.state?.worlds}
function getWorld(id=app.view){return app.room?.state?.worlds?.[id]}
function roomPlayers(){return app.room?.players||{}}
function connectedOther(){return !!roomPlayers()[other(app.player)]}
function roleChange(p){app.persona=p;render()}
function updateRoom(room){app.room=room;app.view=room?.state?.activeWorld||'lobby';render()}
function localPublish(room){localStorage.setItem(roomKey(app.code),JSON.stringify(room));app.localChannel?.postMessage({code:app.code});updateRoom(room)}
async function mutate(fn){if(!app.room)return;try{
 if(app.mode==='firebase'){
  const path=app.api.ref(app.db,'rooms/'+app.code+'/state');
  const result=await app.api.runTransaction(path,current=>{if(!current)return;const draft=structuredClone(current);fn(draft);return draft},{applyLocally:false});
  if(!result.committed)toast('Could not save that move. Please try again.');
 }else{const stored=JSON.parse(localStorage.getItem(roomKey(app.code))||'null')||app.room;const draft=structuredClone(stored.state);fn(draft);stored.state=draft;localPublish(stored)}
}catch(err){console.error(err);toast('Move failed: '+(err.message||'Try again'))}}
async function enterRoom(room,code,persona){app.code=code;app.player=persona;app.uid=app.uid||sessionStorage.getItem('usverse-local-uid')||randomCode();sessionStorage.setItem('usverse-local-uid',app.uid);app.view=room.state?.activeWorld||'lobby';app.room=room;sessionStorage.setItem('usverse-last-room',JSON.stringify({code,persona,mode:app.mode}));if(app.unsub){app.unsub();app.unsub=null}if(app.mode==='firebase'){
 const {ref,onValue}=app.api;app.unsub=onValue(ref(app.db,'rooms/'+code),snap=>{if(snap.exists())updateRoom(snap.val());else{toast('Room was closed');app.room=null;render()}},err=>toast('Live sync error: '+err.message));
}else{app.localChannel?.close();app.localChannel=new BroadcastChannel('usverse-local');app.localChannel.onmessage=e=>{if(e.data?.code===code){const v=JSON.parse(localStorage.getItem(roomKey(code))||'null');if(v)updateRoom(v)}};window.addEventListener('storage',e=>{if(e.key===roomKey(code)&&e.newValue)updateRoom(JSON.parse(e.newValue))});render()}}
async function createRoom(){const persona=app.persona,code=randomCode();const room={createdBy:app.uid||randomCode(),createdAt:now(),players:{[persona]:{uid:app.uid,joinedAt:now()}},state:freshState()};try{if(app.mode==='firebase')await app.api.set(app.api.ref(app.db,'rooms/'+code),room);else localStorage.setItem(roomKey(code),JSON.stringify(room));await enterRoom(room,code,persona);toast('Room established. Share the private code with your person.');confetti()}catch(err){toast('Could not create room: '+err.message)}}
async function joinRoom(){const code=(app.joinCode||$('#join-code')?.value||'').replace(/[^A-Z0-9]/gi,'').toUpperCase();if(code.length!==8){toast('Enter the eight-character room code');return}const persona=app.persona;try{let room;if(app.mode==='firebase'){const snap=await app.api.get(app.api.ref(app.db,'rooms/'+code));room=snap.val()}else room=JSON.parse(localStorage.getItem(roomKey(code))||'null');if(!room){toast('Room not found. Check the code and hosting mode.');return}const slot=room.players?.[persona];if(slot&&slot.uid!==app.uid){toast(`${nice(persona)} is already taken in this room. Choose the other person.`);return}if(!slot){const record={uid:app.uid,joinedAt:now()};if(app.mode==='firebase')await app.api.set(app.api.ref(app.db,`rooms/${code}/players/${persona}`),record);room.players[persona]=record}else if(app.mode==='local')room.players[persona]=slot;if(app.mode==='local')localStorage.setItem(roomKey(code),JSON.stringify(room));await enterRoom(room,code,persona);toast(`Welcome to the universe, ${nice(persona)}.`);sfx(620)}catch(err){console.error(err);toast('Join failed: '+err.message)}}
async function initFirebase(){const config=window.USVERSE_FIREBASE_CONFIG||{};if(!config.apiKey||!config.databaseURL||!config.projectId){app.mode='local';app.uid=sessionStorage.getItem('usverse-local-uid')||randomCode();sessionStorage.setItem('usverse-local-uid',app.uid);return}try{const [f,a,d]=await Promise.all([import('https://www.gstatic.com/firebasejs/13.3.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/13.3.0/firebase-auth.js'),import('https://www.gstatic.com/firebasejs/13.3.0/firebase-database.js')]);const fb=f.initializeApp(config);app.auth=a.getAuth(fb);await a.signInAnonymously(app.auth);app.uid=app.auth.currentUser.uid;app.db=d.getDatabase(fb);app.api=d;app.mode='firebase';app.connected=true}catch(err){console.error(err);app.mode='local';app.connected=false;app.uid=sessionStorage.getItem('usverse-local-uid')||randomCode();sessionStorage.setItem('usverse-local-uid',app.uid);app.firebaseError=err.message}}
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${esc(action)}" ${extra}>${label}</button>`;
const chip=(text,color='')=>`<span class="chip ${color}">${text}</span>`;
const progress=(fraction)=>`<div class="progress" role="progressbar" aria-valuenow="${Math.round(fraction*100)}" aria-valuemin="0" aria-valuemax="100"><div class="bar" style="width:${Math.max(0,Math.min(100,fraction*100))}%"></div></div>`;
const options=(arr,action,selected=null)=>`<div class="options">${arr.map((v,i)=>`<button class="option ${selected===i?'selected':''}" data-action="${action}" data-index="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(v)}</button>`).join('')}</div>`;
const formField=(id,label,placeholder='',type='text',max=400)=>`<label class="label" for="${id}">${label}</label><input class="field" type="${type}" id="${id}" placeholder="${esc(placeholder)}" maxlength="${max}" autocomplete="off" />`;
const worldBy=id=>allWorlds.find(w=>w.id===id);
function topbar(){const s=app.room?.state;return `<header class="topbar"><button class="logo" data-action="home" aria-label="Back to world map"><span class="logo-mark">♥</span> USVERSE</button><div class="topstats">${chip(app.mode==='firebase'?'● LIVE ROOM':'◌ LOCAL PREVIEW',app.mode==='firebase'?'cyan':'pink')}${app.room?chip('ROOM '+app.code):''}${s?chip(`✦ ${s.coins[app.player]} COINS`,'gold'):''}${btn(app.sound?'♫ SOUND ON':'♫ MUTED','toggle-sound','ghost tiny sound')}${app.room?btn('⎋ EXIT','exit','ghost tiny'):''}</div></header>`}
function frame(content){return `<div class="site">${topbar()}<main>${content}</main><footer class="footer"><div class="flex between wrap gap12"><span>USVERSE ♥ KHUSHI × GAURAV. Built for two. No ads, no tracking.</span><span>Private room code ≠ end-to-end encryption. Keep sensitive secrets off the site.</span></div></footer></div>`}
function renderLanding(){return `<div class="hero"><div><div class="eyebrow">☻ CLASSIFIED: TWO PLAYERS ONLY</div><h1>LOVE IS A <span>COMPETITIVE SPORT.</span></h1><p>Escape a mystery together. Destroy each other at cricket. Reveal secrets. Make terrible art. Get flirty. Collect Chaos Coins. Fall in love with the plot twists.</p><div class="btnrow">${chip('12 PLAYABLE WORLDS','pink')}${chip('TWO PLAYER MAYHEM','cyan')}${chip('ACTUAL CONSEQUENCES','gold')}</div></div><div class="hero-art"><div class="orb"><span class="orb-heart">♥</span><div class="orbit-label one">✦ LOVE CASINO</div><div class="orbit-label two">✧ SECRET FILES</div><div class="orbit-label three">⚡ AFTER DARK</div></div></div></div><section class="card login"><div class="tabstrip"><button data-action="login-tab" data-value="create" class="${app.loginTab==='create'?'active':''}">CREATE A ROOM</button><button data-action="login-tab" data-value="join" class="${app.loginTab==='join'?'active':''}">JOIN A ROOM</button></div><p class="eyebrow mb16">01 / IDENTIFY YOURSELF, OPERATIVE</p><div class="flex gap12 mb16"><button class="persona ${app.persona==='khushi'?'selected':''}" data-action="persona" data-value="khushi"><span class="avatar">👑</span>KHUSHI</button><button class="persona ${app.persona==='gaurav'?'selected':''}" data-action="persona" data-value="gaurav"><span class="avatar">⚡</span>GAURAV</button></div>${app.loginTab==='join'?`<div class="mb16">${formField('join-code','PRIVATE ROOM CODE','8-character code','text',8)}</div>`:''}<div class="btnrow">${btn(app.loginTab==='create'?'OPEN THE UNIVERSE →':'JOIN MY PERSON →',app.loginTab==='create'?'create':'join','primary fill')}</div><p class="hint mt16">${app.mode==='firebase'?'✓ Live multiplayer is connected. You can play on separate devices.':'⚠ Preview mode: play in two tabs on the same browser. To play across devices, connect Firebase in firebase-config.js before uploading to Netlify.'}${app.firebaseError?'<br>Firebase issue: '+esc(app.firebaseError):''}</p></section><p class="credit center">PERSONALITY WARNING: highly competitive. play responsibly. ♡</p>`}
function board(s){return `<div class="scoreboard"><div class="playercard"><div class="playeravatar">♛</div><div><div class="small strong">KHUSHI ${app.player==='khushi'?'(YOU)':''}</div><div class="score">${s.scores.khushi}</div><div class="hint">✦ ${s.coins.khushi} coins</div></div></div><div class="versus">VS<br>♥</div><div class="playercard right"><div class="playeravatar gb">⚡</div><div><div class="small strong">GAURAV ${app.player==='gaurav'?'(YOU)':''}</div><div class="score">${s.scores.gaurav}</div><div class="hint">✦ ${s.coins.gaurav} coins</div></div></div></div>`}
function renderLobby(){const s=app.room.state,partner=connectedOther();return `<div class="roomhead"><div class="eyebrow">WELCOME TO YOUR PRIVATE UNIVERSE</div><div class="flex items between wrap gap12"><h1>HEY, <span>${app.player.toUpperCase()}.</span> GAME ON.</h1>${btn('⧉ COPY ROOM CODE','copy-code','tiny')}</div><p class="muted mt8">Room <b>${app.code}</b> · ${partner?'Both operatives are in. The chaos can begin.':'Waiting for '+nice(other(app.player))+' to join with your code.'}</p></div>${board(s)}${!partner?`<div class="alert mt16">🔐 Share this room code privately with ${nice(other(app.player))}. You can explore alone; two-player games wait for both of you.</div>`:''}<div class="section-header"><div class="eyebrow">THE MASTER CONTROL ROOM</div><h2>Pick your poison.</h2><p>Every door has actual gameplay. Your coins, points, artworks and memories carry across the universe.</p></div><div class="grid four worldgrid">${allWorlds.map((w,i)=>`<button class="worldcard ${i===0?'featured':''}" style="--tone:${w.tone}" data-action="open-world" data-id="${w.id}"><div class="emoji">${w.emoji}</div><h3>${w.name}</h3><p>${w.desc}</p><div class="worldmeta"><span>${w.time}</span><span>${w.mode}</span></div><span class="num">${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><div class="grid two mt24"><section class="card"><div class="eyebrow">CLASSIFIED SIDE QUEST</div><h3 class="mt8">Your secret mission</h3><p class="mt8">${esc(missions[app.player][s.missions[app.player].id])}</p><div class="mt16">${s.missions[app.player].done?chip('✓ MISSION CLAIMED','cyan'):btn('I COMPLETED MY MISSION (+30 COINS)','mission-claim','tiny gold')}</div><p class="hint mt8">Honour system. Do not reveal the objective until you have completed it.</p></section><section class="card"><div class="eyebrow">LATEST INCIDENT REPORTS</div><h3 class="mt8">What just happened</h3><div class="timeline mt16">${(s.feed.length?s.feed:[{text:'Your universe is waiting for its first scandal.'}]).slice(0,5).map((f,i)=>`<div class="timeline-row"><span class="timeline-num">${String(i+1).padStart(2,'0')}</span><span class="small">${esc(f.text)}</span></div>`).join('')}</div></section></div>`}
function worldShell(w,content){return `<div class="worldhero" style="--tone:${w.tone}"><div class="flex items between wrap gap12"><div>${btn('← ALL WORLDS','home','ghost tiny')}<div class="worldemoji mt16">${w.emoji}</div><p class="stage">${w.mode} / ${w.time} / ${w.tag.toUpperCase()}</p><h2>${w.name}</h2><p>${w.desc}</p></div><div>${chip(`YOU: ${nice(app.player)}`,'pink')}</div></div></div>${content}`}
function render(){const root=$('#app');if(!root)return;const s=app.room?.state;let html;if(!app.room)html=renderLanding();else if(!s||app.view==='lobby')html=renderLobby();else{const w=worldBy(app.view);if(!w){html=renderLobby()}else{const renderers={mystery:renderMystery,cricket:renderCricket,mind:renderMind,trivia:renderTrivia,art:renderArt,hot:renderHot,casino:renderCasino,court:renderCourt,jukebox:renderJukebox,multiverse:renderMultiverse,cinema:renderCinema,vault:renderVault};html=worldShell(w,(renderers[app.view]||(()=>'<p>Coming soon</p>'))())}}root.innerHTML=frame(html);if(app.view==='art')setupCanvas();tickTimers()}

/* ───────────────────────────────── GAME WORLDS ───────────────────────────────── */
function renderMystery(){const m=getWorld('mystery');if(m.completed){return `<section class="card bright center"><div style="font-size:4.5rem">🏆🔓</div><div class="eyebrow mt16">CASE CLOSED / MYSTERY SOLVED</div><h2 class="mt16">You defeated the Third Wheel.</h2><p class="muted mt16">Two different screens. Five locked rooms. One undefeated team. Your memory vault is safe. For now.</p><div class="btnrow mt24" style="justify-content:center">${btn('PLAY AGAIN','mystery-reset','primary')}${btn('VISIT THE VAULT','open-world','',`data-id="vault"`)}</div></section>`}if(!m.startedAt)return `<div class="grid two"><section class="card"><div class="eyebrow">MISSION BRIEFING</div><h3 class="mt16">The Third Wheel Protocol</h3><p class="muted mt16">An unknown villain has taken five relationship files hostage. Every file is a different type of lock. Your screens contain different clues. You'll need to talk, not just click.</p><div class="prompt-list mt24"><div>🔎 Five linked rooms</div><div>👥 Role-specific clues</div><div>⏱ A 35-minute countdown</div><div>💰 Paid hints and sneaky side deals</div></div>${btn('BEGIN THE OPERATION →','mystery-start','primary mt24',connectedOther()?'':'disabled title="Both players need to join"')}</section><section class="card bright"><span class="eyebrow">CLASSIFIED DOSSIER</span><div class="lock">⟡ ▧ ◈</div><p class="muted">Mission number: #KV-GB-001</p><p class="muted mt16">If an operative takes the secret shortcut, the operation becomes harder for both people. Love, trust and a little treachery. What could possibly go wrong?</p><div class="callout mt24">For the best experience: be on a video call, open the site on separate devices, and do not screen-share the puzzle clues.</div></section></div>`;
const st=mysteryStages[m.stage];const elapsed=now()-m.startedAt;const extra=(m.hints||0)*45000+(Object.values(m.deals||{}).filter(Boolean).length)*60000;const left=Math.max(0,35*60000-elapsed-extra);return `<div class="grid two"><section class="card"><div class="flex items between gap12"><div><div class="eyebrow">${esc(st?.place||'FINAL')}</div><h3 class="mt8">${esc(st?.title||'Case closed')}</h3></div><span class="timer" data-timer="mystery">${formatTime(left)}</span></div><div class="mt16">${progress(m.stage/mysteryStages.length)}</div><p class="hint mt8">LOCK ${m.stage+1} OF ${mysteryStages.length} · HINTS USED: ${m.hints} · TIMER IS SHARED</p><div class="puzzle-clue mt24">${esc(app.player==='khushi'?st?.a:st?.b)}</div><p class="hint mt16">This clue appears only on ${nice(app.player)}'s screen. Tell your partner what you see.</p>${m.hintShown?`<div class="callout mt16"><b>PAID HINT:</b> ${esc(m.hintShown)}</div>`:''}<div class="mt24">${formField('mystery-answer','ENTER THE SHARED LOCK CODE',st?.placeholder||'Code','text',20)}</div><div class="btnrow mt16">${btn('UNLOCK FILE →','mystery-submit','primary fill')}${btn('HINT • 15 COINS','mystery-hint','tiny',app.room.state.coins[app.player]<15?'disabled':'')}</div></section><section class="card"><div class="eyebrow">INTERFERENCE DETECTED</div><h3 class="mt8">Trust, or take the deal?</h3><p class="muted mt16">A mysterious voice offers you <b class="gold">25 Chaos Coins</b> for taking the shortcut. The catch: the mission loses an extra minute. Your partner will find out.</p>${m.deals?.[`${m.stage}_${app.player}`]?'<div class="reveal mt16">Side deal claimed. You absolute menace.</div>':btn('TAKE THE SIDE DEAL','mystery-deal','warn mt16')}<div class="line"></div><h3>Encrypted terminal</h3><p class="muted mt16">${m.hints?'The files are becoming unstable. Keep talking and combine your clues.':'The security terminal shows no further information. A hint will reveal the current room’s solution pattern.'}</p><p class="hint mt16">If you run out of time, the room stays open. You can still finish without losing your progress.</p></section></div>`}
function formatTime(ms){const s=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function cricketRole(c){const batter=c.inning===0?'khushi':'gaurav';return {batter,bowler:other(batter),i:c.inning}}
function renderCricket(){const c=getWorld('cricket');const {batter,bowler,i}=cricketRole(c),batting=batter===app.player;const balls=c.history.filter(x=>x.inning===i);const recent=c.history.at(-1);const score=c.totals[i]||0,wickets=c.wickets[i]||0;return `<div class="grid two"><section class="card"><div class="flex between items wrap gap12"><div><div class="eyebrow">THE KHUSHI–GAURAV CUP</div><h3 class="mt8">${c.done?'MATCH COMPLETE':`INNINGS ${i+1} · ${nice(batter)} BATTING`}</h3></div>${chip(`${score}/${wickets} · ${Math.floor(c.ball/6)}.${c.ball%6} OVERS`,'gold')}</div><div class="pitch"><div class="pitch-strip"></div><div class="stumps top"></div><div class="stumps bottom"></div><div class="pitch-ball">🏏</div><div class="pitch-bat">🏃</div><div class="pitch-result">${c.done?'🏆 FULL TIME':recent?.inning===i?esc(recent.label):'PLAY BALL!'}</div></div><div class="balls">${balls.length?balls.map(b=>`<span class="${b.wicket?'w':b.runs===6?'six':''}">${b.wicket?'W':b.runs}</span>`).join(''):'<span>•</span><span>•</span><span>•</span><span>•</span><span>•</span><span>•</span>'}</div><div class="line"></div><div class="grid two"><div><div class="overline">KHUSHI</div><h2>${c.totals[0]}/${c.wickets[0]}</h2></div><div><div class="overline">GAURAV</div><h2>${c.totals[1]}/${c.wickets[1]}</h2></div></div></section><section class="card">${c.done?`<div class="eyebrow">FINAL RESULT</div><h2 class="mt16">${c.totals[0]===c.totals[1]?'A perfectly infuriating TIE.':`${c.totals[0]>c.totals[1]?'Khushi':'Gaurav'} wins the Cup!`}</h2><p class="muted mt16">Winning by cricket, not by being insufferably attractive. Though both may apply.</p>${btn('REMATCH ↻','cricket-reset','primary mt24')}`:`<div class="eyebrow">YOUR SECRET CONTROL PANEL</div><h3 class="mt8">${batting?'🏏 YOU ARE BATTING':'🎯 YOU ARE BOWLING'}</h3><p class="muted mt16">${batting?'Predict the delivery. Choose timing and shot placement. Higher aggression can mean more runs or an embarrassing wicket.':'Make the batter misread you. Set line and pace, then send your delivery. They cannot see your selection.'}</p>${c.choices[app.player]?`<div class="reveal mt24">✓ ${batting?'Shot locked in.':'Delivery sent.'} Waiting for ${nice(other(app.player))}…</div>`:`<div class="grid two mt24"><div><label class="label" for="cricket-a">${batting?'SHOT DIRECTION':'BOWLING LINE'}</label><select class="field" id="cricket-a"><option value="1">${batting?'Leg side':'Leg stump'}</option><option value="2" selected>${batting?'Straight':'Middle stump'}</option><option value="3">${batting?'Off side':'Off stump'}</option></select></div><div><label class="label" for="cricket-b">${batting?'SHOT TIMING':'DELIVERY PACE'}</label><select class="field" id="cricket-b"><option value="1">Early / Slow</option><option value="2" selected>Middle / Normal</option><option value="3">Late / Fast</option></select></div></div><div class="mt16"><label class="label" for="cricket-c">${batting?'SHOT STYLE':'SPECIAL BALL'}</label><select class="field" id="cricket-c">${batting?'<option value="1">Defensive — low risk</option><option value="2" selected>Controlled drive</option><option value="3">All-or-nothing helicopter shot</option>':'<option value="1">Yorker</option><option value="2" selected>Good length</option><option value="3">Bouncer</option>'}</select></div>${btn(batting?'PLAY SHOT 🏏':'BOWL BALL 🎯','cricket-play','primary mt24 full')}`}<div class="line"></div><p class="small muted">${c.choices[other(app.player)]?'⚡ Your partner is ready.':'⏳ Waiting on partner’s move.'} One innings each. Six deliveries, or two wickets. Choices are revealed after both commit.</p>`}</section></div>`}
function renderMind(){const m=getWorld('mind');const predict=m.mode==='predict',idx=predict?m.idx:m.deepIdx;const q=predict?mindQuestions[idx%mindQuestions.length]:deepQuestions[idx%deepQuestions.length];const mine=m.answers[app.player],guess=m.guesses[app.player];return `<div class="tabstrip"><button class="${predict?'active':''}" data-action="mind-mode" data-value="predict">🧠 PREDICT ME</button><button class="${!predict?'active':''}" data-action="mind-mode" data-value="deep">💗 DEEP TALK</button></div><div class="grid two"><section class="card"><div class="eyebrow">${predict?`QUESTION ${(idx%mindQuestions.length)+1} OF ${mindQuestions.length}`:`HONESTY FILE ${(idx%deepQuestions.length)+1} OF ${deepQuestions.length}`}</div><div class="bigquestion mt24 mb16">${esc(q.q||q)}</div>${predict?renderMindPredict(m,q):renderMindDeep(m,q)}<div class="mt24">${progress(((idx%mindQuestions.length)+1)/mindQuestions.length)}</div></section><section class="card bright"><div class="eyebrow">THE RULES</div><h3 class="mt16">${predict?'You can know someone and still be surprised.':'No scoreboard. No interrupting. Just you two.'}</h3><p class="muted mt16">${predict?'First choose YOUR own answer privately. Then predict what your partner chose. You score only for getting their answer right. Both reveal simultaneously.':'Both write an answer, then read each other’s response. You can disagree, laugh, ask follow-ups or sit with a surprisingly sweet answer.'}</p><div class="callout mt24">${predict?'Both of you must submit your answers and predictions. Correct predictions earn 20 points and 10 coins.':'This mode is deliberately not scored. It exists for the things you forget to ask during ordinary calls.'}</div></section></div>`}
function renderMindPredict(m,q){const me=app.player,them=other(me),mine=m.answers[me],guess=m.guesses[me];if(m.revealed){const gotMine=m.guesses[me]===m.answers[them];return `<div class="reveal mt24"><h3>THE REVEAL ✨</h3><div class="scoretable mt16"><div class="scorerow"><b>Khushi chose</b><span>${esc(q.options[m.answers.khushi])}</span></div><div class="scorerow"><b>Gaurav chose</b><span>${esc(q.options[m.answers.gaurav])}</span></div><div class="scorerow"><b>You predicted</b><span>${esc(q.options[m.guesses[me]])}</span></div></div><p class="mt16 strong">${gotMine?'Correct! You know your person. +20 points':'Wrong. Time to investigate your assumptions. 😭'}</p></div>${btn('NEXT QUESTION →','mind-next','primary mt24')}`}
if(mine===undefined)return `<p class="hint mt16 mb16">STEP 1: CHOOSE YOUR OWN ANSWER. Only your selection is shown here until the reveal.</p>${options(q.options,'mind-answer')}`;
if(guess===undefined)return `<div class="callout mt16">Your secret answer is locked: <b>${esc(q.options[mine])}</b>.</div><p class="hint mt24 mb16">STEP 2: WHAT DO YOU THINK ${nice(them).toUpperCase()} CHOSE?</p>${options(q.options,'mind-guess')}`;
return `<div class="reveal mt24">Your guess is locked. ${m.guesses[them]===undefined?'Waiting for your partner to finish…':'Revealing results…'}</div>`}
function renderMindDeep(m){const me=app.player,them=other(me);if(m.deepRevealed)return `<div class="letter mt24">${esc(nice(me))}: ${esc(m.deepAnswers[me])}\n\n${esc(nice(them))}: ${esc(m.deepAnswers[them])}</div>${btn('ANOTHER REAL QUESTION →','mind-deep-next','primary mt24')}`;if(m.deepAnswers[me]!==undefined)return `<div class="reveal mt24">Your response is safely submitted. Waiting for ${nice(them)} to share theirs.</div>`;return `<textarea class="field mt24" id="deep-answer" placeholder="Say what you mean. Your answer stays hidden until you have both submitted..." maxlength="600"></textarea>${btn('SEAL MY ANSWER ♥','mind-deep-submit','primary mt16')}`}
const triviaBank=[...quotes.map(q=>({type:'quote',...q})),...lore.map(q=>({type:'lore',...q}))];
function renderTrivia(){const t=getWorld('trivia'),q=triviaBank[t.idx],me=app.player;const complete=t.idx>=triviaBank.length||t.done;if(complete)return `<section class="card center bright"><div style="font-size:4rem">📜🏆</div><h2 class="mt16">The Receipts are CLOSED.</h2><p class="muted mt16">You survived the relationship archives. Congratulations on being historically questionable.</p>${btn('REOPEN THE ARCHIVE','trivia-reset','primary mt24')}</section>`;
const revealed=t.choices.khushi!==undefined&&t.choices.gaurav!==undefined;const correct=q.type==='quote'?(q.by==='khushi'?0:1):q.answer;return `<div class="grid two"><section class="card"><div class="flex between items gap12"><div class="eyebrow">${q.type==='quote'?'WHO SAID IT?':'RELATIONSHIP LORE'}</div>${chip(`${t.idx+1}/${triviaBank.length}`)}</div>${progress(t.idx/triviaBank.length)}<div class="quote">${q.type==='quote'?`“${esc(q.text)}”`:esc(q.q)}</div>${revealed?`<div class="reveal"><h3>THE RECEIPT IS REAL.</h3><p class="mt8">Correct answer: <b>${esc(q.type==='quote'?nice(q.by):q.choices[correct])}</b></p><div class="scoretable mt16">${['khushi','gaurav'].map(p=>`<div class="scorerow"><span>${nice(p)}</span><strong>${t.choices[p]===correct?'✓ RIGHT':'✗ WRONG'}</strong></div>`).join('')}</div></div>${btn('NEXT RECEIPT →','trivia-next','primary mt24')}`:t.choices[me]!==undefined?'<div class="reveal">Answer sealed. Waiting for your accomplice.</div>':options(q.type==='quote'?['Khushi','Gaurav']:q.choices,'trivia-vote')}</section><section class="card"><div class="eyebrow">WHY IS THIS SO PERSONAL?</div><h3 class="mt16">Your messages, turned into a game.</h3><p class="muted mt16">These are selected, non-explicit snippets and harmless details from conversations you shared. No raw chat files are uploaded to this site.</p><div class="callout mt24">The questions are personal, but some are deliberately easy. The real challenge is whether your partner remembers their own nonsense.</div><p class="hint mt24">Your answer is hidden until both players lock theirs in. +15 points per correct answer.</p></section></div>`}
function renderArt(){const a=getWorld('art');return `<div class="grid two"><section class="card"><div class="flex between items wrap gap12"><div><div class="eyebrow">COLLABORATIVE CANVAS / ROUND ${a.idx+1}</div><h3 class="mt8">The masterpiece nobody requested.</h3></div>${chip(`${a.strokes.length} STROKES`,'cyan')}</div><div class="callout mt16"><b>YOUR PROMPT:</b> ${esc(artPrompts[a.idx%artPrompts.length])}</div><div class="mt16"><canvas id="draw-canvas" class="drawing" width="880" height="600" aria-label="Shared drawing canvas"></canvas></div><div class="flex between items wrap gap12 mt16"><div class="palette">${['#db4a88','#7054d4','#1671c0','#12a36a','#f1a52a','#1d253b','#ffffff'].map(color=>`<button data-action="art-color" data-value="${color}" class="swatch ${app.brush===color&&!app.eraser?'active':''}" aria-label="Choose ${color}" style="background:${color}"></button>`).join('')}${btn('ERASER','art-erase','tiny '+(app.eraser?'selected':''))}</div><div class="flex gap8">${btn('UNDO','art-undo','tiny')}${btn('CLEAR','art-clear','tiny warn')}</div></div><div class="btnrow mt16">${btn('SAVE PNG ↓','art-save','tiny')}${btn('NEW PROMPT →','art-next','primary fill')}</div></section><section class="card"><div class="eyebrow">THE ARTIST’S MANIFESTO</div><h3 class="mt16">Draw together, live.</h3><p class="muted mt16">Both of you draw on the same canvas. Each completed stroke syncs to the other screen. You can scribble over each other's questionable creations.</p><div class="prompt-list mt24"><div>🎨 Six colours + eraser</div><div>🖍️ Works with mouse, touch or stylus</div><div>💌 Export the resulting masterpiece as PNG</div><div>🌀 Each prompt gets worse</div></div><div class="line"></div><div class="overline">GALLERY WALL</div>${a.finished.length?`<div class="timeline mt16">${a.finished.slice(-5).reverse().map(p=>`<div class="timeline-row"><span class="timeline-num">✦</span><span class="small">${esc(p.prompt)} · ${p.strokes} strokes</span></div>`).join('')}</div>`:'<p class="hint mt16">Your gallery awaits its first disaster.</p>'}</section></div>`}
function hotLevel(h){return ['flirty','unhinged','afterdark'][Math.min(['flirty','unhinged','afterdark'].indexOf(h.level.khushi),['flirty','unhinged','afterdark'].indexOf(h.level.gaurav))]}
function hotCard(h){const level=hotLevel(h),pool=level==='flirty'?hotDeck.flirty:level==='unhinged'?[...hotDeck.flirty,...hotDeck.unhinged]:[...hotDeck.flirty,...hotDeck.unhinged,...hotDeck.afterdark];return pick(pool,`${app.code}-spicy-${h.idx}`)}
function renderHot(){const h=getWorld('hot'),me=app.player,them=other(me);const ready=!!h.consents.khushi&&!!h.consents.gaurav,level=hotLevel(h),card=hotCard(h);return `<div class="grid two"><section class="card afterdark"><div class="eyebrow">THE AFTER DARK CLUB</div><div class="roulette mt16">💋</div><h2 class="mt16">HOT MESS.</h2><p class="muted mt16">Flirting, unpredictable confessions and the kind of banter that makes you forget you're on a video call.</p><div class="line"></div><label class="label" for="hot-level">YOUR COMFORT LEVEL</label><select class="field" id="hot-level"><option value="flirty" ${h.level[me]==='flirty'?'selected':''}>💗 Flirty</option><option value="unhinged" ${h.level[me]==='unhinged'?'selected':''}>🔥 Unhinged</option><option value="afterdark" ${h.level[me]==='afterdark'?'selected':''}>🌙 After Dark (18+)</option></select><p class="hint mt16">The active level is the lower of your two selections. Either person can skip any card, for any reason, with no penalty.</p><div class="mt16">${h.consents[me]?chip('✓ YOU OPTED IN','cyan'):btn('I CONSENT TO PLAY','hot-consent','primary full')}</div><p class="hint mt16">${h.consents[them]?'✓ Partner is ready.':'⏳ Waiting for partner to opt in.'}</p></section><section class="card bright">${!ready?`<div class="eyebrow">VELVET ROPE</div><h3 class="mt16">Both of you decide how far this goes.</h3><p class="muted mt16">We keep this playful, consensual and non-graphic. If either of you wants to slow down, change the level or skip, the website will follow.</p><div class="lock">♥ ♥</div>`:`<div class="eyebrow">CARD ${h.idx+1} / ${level.toUpperCase()}</div><div class="afterdark mt16"><span class="tagline">${esc(card.type)}</span><div class="bigquestion mt24">${esc(card.q)}</div></div><div class="mt24">${h.done[me]?chip('✓ YOUR TURN COMPLETE','cyan'):btn('CHALLENGE DONE ✓','hot-done','primary full')}</div><div class="btnrow mt16">${btn('SKIP WITHOUT PENALTY','hot-skip','tiny')}${btn('RESET CONSENT','hot-unconsent','tiny warn')}</div><p class="hint mt16">${h.done[them]?'Your partner finished the card.':'Partner’s action is still pending.'} A completed card earns each participating player 8 Chaos Coins.</p>`}</section></div>`}
function renderCasino(){const c=getWorld('casino'),me=app.player,them=other(me);return `<div class="grid two"><section class="card bright"><div class="eyebrow">MIDNIGHT CASINO • ROUND ${c.round+1}</div><div class="center mt24" style="font-size:4.6rem">🎰</div><h2 class="center mt16">RED OR BLACK?</h2><p class="muted center mt16">Choose your wager, predict the roulette colour, and make your opponent question every life decision. Both selections reveal together.</p>${c.last?`<div class="callout mt24">LAST SPIN: <b>${esc(c.last.result.toUpperCase())}</b> · ${esc(c.last.summary)}</div>`:''}<div class="line"></div><div class="grid two"><div><div class="overline">YOUR BANK</div><h2>${app.room.state.coins[me]} ✦</h2></div><div><div class="overline">OPPONENT BANK</div><h2>${app.room.state.coins[them]} ✦</h2></div></div><p class="hint mt16">This uses fictional game currency. No money, payments or gambling.</p></section><section class="card"><div class="eyebrow">PLACE YOUR BET</div><h3 class="mt16">Trust your instinct or bluff your way through.</h3>${c.bets[me]?`<div class="reveal mt24">Your ${c.bets[me].bet}-coin bet on ${esc(c.bets[me].color)} is sealed. ${c.bets[them]?'Spinning…':'Waiting for partner.'}</div>`:`<div class="mt24"><label class="label">SELECT WAGER</label><div class="btnrow">${[10,25,50].map(n=>`<button class="btn tiny" data-action="casino-bet" data-bet="${n}" data-color="red" ${app.room.state.coins[me]<n?'disabled':''}>🔴 ${n} ON RED</button>`).join('')}</div><div class="btnrow mt16">${[10,25,50].map(n=>`<button class="btn tiny" data-action="casino-bet" data-bet="${n}" data-color="black" ${app.room.state.coins[me]<n?'disabled':''}>⚫ ${n} ON BLACK</button>`).join('')}</div></div>`}<div class="line"></div><h3>Recent spins</h3><div class="scoretable mt16">${c.outcomes.slice(-5).reverse().map(o=>`<div class="scorerow"><span>Round ${o.round}</span><b class="${o.result==='red'?'accent':'cyan'}">${o.result==='red'?'🔴 RED':'⚫ BLACK'}</b></div>`).join('')||'<p class="hint">The wheel has not spun yet.</p>'}</div></section></div>`}
function renderCourt(){const c=getWorld('court'),charge=charges[c.round%charges.length],me=app.player,them=other(me),prosecutor=c.round%2===0?'khushi':'gaurav';const revealed=!!c.last&&c.last.round===c.round;return `<div class="grid two"><section class="card"><div class="eyebrow">THE HONOURABLE COURT OF US / CASE ${c.round+1}</div><div class="center mt24" style="font-size:4rem">⚖️</div><h2 class="center mt16">${esc(charge)}</h2><p class="muted center mt16">${nice(prosecutor)} is prosecuting. ${nice(other(prosecutor))} is defending. Both select a tactic in secret, then make a closing argument.</p><div class="line"></div><p class="hint">TACTIC RULES: Receipt beats Alibi, Alibi beats Witness, Witness beats Receipt. Equal tactics make a hung jury.</p><div class="btnrow mt16">${btn('NEXT CASE →','court-next','tiny',revealed?'':'disabled')}${btn('RESET COURT','court-reset','ghost tiny')}</div></section><section class="card">${revealed?`<div class="eyebrow">THE JURY HAS SPOKEN</div><h3 class="mt16">${esc(c.last.summary)}</h3><div class="scoretable mt24">${['khushi','gaurav'].map(p=>`<div class="scorerow"><span>${nice(p)} · ${esc(c.last.choices[p].tactic)}</span><span>${esc(c.last.choices[p].statement)}</span></div>`).join('')}</div>${btn('CALL THE NEXT CASE →','court-next','primary mt24')}`:c.choices[me]?`<div class="reveal">Your argument is submitted. Waiting for ${nice(them)} to finish filing their evidence.</div>`:`<div class="eyebrow">YOUR CASE</div><h3 class="mt16">${me===prosecutor?'Make your accusation.':'Defend your reputation.'}</h3><label class="label mt24" for="court-tactic">SECRET TACTIC</label><select class="field" id="court-tactic"><option value="receipt">📸 The Receipt</option><option value="alibi">🕶 The Alibi</option><option value="witness">🧑‍⚖️ Surprise Witness</option></select><label class="label mt16" for="court-statement">YOUR CLOSING ARGUMENT</label><textarea id="court-statement" class="field" maxlength="180" placeholder="Your honour, the evidence clearly shows..." ></textarea>${btn('SUBMIT EVIDENCE →','court-submit','primary mt16 full')}`}</section></div>`}
function renderJukebox(){const j=getWorld('jukebox'),q=musicQs[j.idx],me=app.player;if(j.done||j.idx>=musicQs.length)return `<section class="card center"><div style="font-size:4rem">🎤🏆</div><h2 class="mt16">Jukebox closed.</h2><p class="muted mt16">A music battle for the ages.</p>${btn('ENCORE ↻','jukebox-reset','primary mt24')}</section>`;const revealed=j.choices.khushi!==undefined&&j.choices.gaurav!==undefined;return `<div class="grid two"><section class="card bright"><div class="eyebrow">TRACK ${j.idx+1} / ${musicQs.length}</div>${progress(j.idx/musicQs.length)}<div style="font-size:3.5rem" class="mt24">🎧</div><div class="bigquestion mt16 mb16">${esc(q.q)}</div>${revealed?`<div class="reveal mt24"><h3>THE CORRECT ANSWER</h3><p class="mt8">${esc(q.choices[q.answer])}</p><p class="mt16">Khushi: ${j.choices.khushi===q.answer?'✓':'✗'} · Gaurav: ${j.choices.gaurav===q.answer?'✓':'✗'}</p></div>${btn('NEXT TRACK →','jukebox-next','primary mt24')}`:j.choices[me]!==undefined?'<div class="reveal mt24">Answer locked. Waiting for partner.</div>':options(q.choices,'jukebox-vote')}</section><section class="card"><div class="eyebrow">THE SETLIST</div><h3 class="mt16">Taylor, pop and terrible competitive energy.</h3><p class="muted mt16">Guess the artist, song or album. No copyrighted recordings are embedded; you can listen to your favourites together in your own music app during the round.</p><div class="callout mt24">+15 points per correct answer. Bonus bragging rights if you can sing the answer without breaking character.</div></section></div>`}
function renderMultiverse(){const m=getWorld('multiverse'),d=destinations[m.round%destinations.length],me=app.player,them=other(me),c=m.choices;const done=c.khushi&&c.gaurav,activities=['Street food crawl','Sports or adventure','Music and nightlife','Quiet romantic wandering'];return `<div class="grid two"><section class="card bright"><div class="eyebrow">TELEPORTATION ROULETTE / STOP ${m.round+1}</div><div class="center mt16" style="font-size:4.5rem">${d.emoji}</div><h2 class="center mt8">${esc(d.city)}</h2><p class="center muted mt16">${esc(d.vibe)}</p><div class="center mt24"><a class="btn tiny" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(d.city)}" target="_blank" rel="noopener noreferrer">EXPLORE THE CITY ↗</a></div><div class="line"></div><p class="hint">Both secretly pick the sort of date you'd plan here. Match answers to earn points. No cheating by peeking!</p></section><section class="card">${done?`<div class="eyebrow">THE PARALLEL UNIVERSE REVEAL</div><h3 class="mt16">${c.khushi.activity===c.gaurav.activity?'SAME WAVELENGTH! +18 POINTS EACH':'Different planets. Same relationship.'}</h3><div class="scoretable mt24"><div class="scorerow"><b>Khushi picked</b><span>${esc(activities[c.khushi.activity])}</span></div><div class="scorerow"><b>Gaurav picked</b><span>${esc(activities[c.gaurav.activity])}</span></div></div><p class="muted mt16">${nice(me)}: ${esc(c[me].plan||'No plan')}<br>${nice(them)}: ${esc(c[them].plan||'No plan')}</p>${btn('TELEPORT AGAIN ↗','multiverse-next','primary mt24')}`:c[me]?`<div class="reveal">Your imaginary date is sealed. Waiting for your co-traveller.</div>`:`<div class="eyebrow">BUILD A SECRET DATE</div><h3 class="mt16">What are we doing here?</h3><div class="mt24"><label class="label" for="multi-activity">YOUR DATE VIBE</label><select class="field" id="multi-activity">${activities.map((a,i)=>`<option value="${i}">${esc(a)}</option>`).join('')}</select></div><div class="mt16"><label class="label" for="multi-plan">YOUR 1-SENTENCE MASTER PLAN</label><textarea id="multi-plan" class="field" maxlength="190" placeholder="I'd take you to ... and then ..."></textarea></div>${btn('LOCK MY DATE PLAN →','multiverse-submit','primary mt24 full')}`}</section></div>`}
function renderCinema(){const c=getWorld('cinema'),me=app.player,them=other(me);if(c.act>=3)return `<section class="card bright center"><div style="font-size:4rem">🎬🏆</div><h2 class="mt16">YOUR FEATURE FILM IS COMPLETE.</h2><p class="muted mt16">A masterpiece that the Oscars were too scared to nominate.</p><div class="timeline mt24">${c.movie.map((act,i)=>`<div class="timeline-row"><div><div class="eyebrow">ACT ${i+1}</div><p class="mt8"><b>Khushi:</b> ${esc(act.khushi)}</p><p class="mt8"><b>Gaurav:</b> ${esc(act.gaurav)}</p></div></div>`).join('')}</div><div class="btnrow mt24" style="justify-content:center">${btn('DOWNLOAD THE SCREENPLAY','cinema-save','gold')}${btn('SEQUEL ↻','cinema-reset','primary')}</div></section>`;const revealed=c.entries.khushi&&c.entries.gaurav;return `<div class="grid two"><section class="card bright"><div class="eyebrow">HOLLYWOOD IS NOT READY / ACT ${c.act+1} OF 3</div><div class="center mt16" style="font-size:4rem">🎥</div><div class="bigquestion mt24">${esc(filmPrompts[c.act])}</div><p class="muted mt16">Write your own version without seeing what your partner writes. Reveal both scenes and assemble the most chaotic love story in cinematic history.</p>${progress((c.act+1)/3)}</section><section class="card">${revealed?`<div class="eyebrow">DIRECTOR'S CUT: ACT ${c.act+1}</div><div class="callout mt16"><b>Khushi:</b> ${esc(c.entries.khushi)}</div><div class="callout mt16"><b>Gaurav:</b> ${esc(c.entries.gaurav)}</div>${btn('NEXT ACT →','cinema-next','primary mt24')}`:c.entries[me]?'<div class="reveal">Scene submitted. Your co-star is still writing the script.</div>':`<div class="eyebrow">YOUR SECRET SCENE</div><h3 class="mt16">Take this in your own direction.</h3><textarea id="cinema-entry" class="field mt24" maxlength="320" placeholder="INT. MOST INAPPROPRIATE LOCATION — NIGHT. The plot thickens..."></textarea>${btn('SUBMIT MY SCENE →','cinema-submit','primary mt16 full')}`}</section></div>`}
function renderVault(){const v=getWorld('vault'),me=app.player,them=other(me),opened=!!v.letters.khushi&&!!v.letters.gaurav;return `<div class="grid two"><section class="card bright"><div class="eyebrow">PERSONAL ARCHIVE / FOR EYES ONLY</div><h2 class="mt16">The Vault. ❤️</h2><p class="muted mt16">The part of the universe that isn't about winning. Write each other something you want them to keep, even after this website has served its purpose.</p><div class="line"></div>${opened?`<div class="eyebrow">TWO LETTERS, UNLOCKED</div><h3 class="mt16">To ${nice(me)}, from ${nice(them)}</h3><div class="letter mt16">${esc(v.letters[them])}</div><h3 class="mt24">To ${nice(them)}, from ${nice(me)}</h3><div class="letter mt16">${esc(v.letters[me])}</div>${btn('SAVE BOTH LETTERS ↓','vault-export','primary mt24')}`:v.letters[me]?'<div class="reveal mt24">Your letter is sealed. Your partner’s letter will appear when both have written theirs.</div>':`<label class="label mt24" for="vault-letter">WRITE A LETTER YOUR PARTNER WILL OPEN</label><textarea class="field" id="vault-letter" maxlength="1200" style="min-height:180px" placeholder="Hey, you. One thing I never want you to forget is..."></textarea>${btn('SEAL THIS LETTER ♥','vault-submit','primary mt16 full')}`}<p class="hint mt16">Only submit what you're comfortable storing in your own Firebase database. Use the export button to keep a local copy.</p></section><section class="card"><div class="eyebrow">OUR NEXT CHAPTER</div><h3 class="mt16">The reunion bucket list</h3><p class="muted mt16">Things to do when kilometres stop being part of the relationship.</p><div class="mt24">${formField('bucket-entry','ADD A SHARED DREAM','Play cricket somewhere ridiculous','text',150)}</div>${btn('ADD TO OUR LIST +','vault-bucket','tiny mt16')}${v.bucket.length?`<div class="mt24">${v.bucket.map((item,i)=>`<div class="bucket"><div><span class="${item.done?'muted':''}">${item.done?'✓ ':''}${esc(item.text)}</span><div class="hint">Added by ${nice(item.by)}</div></div>${btn(item.done?'REOPEN':'DONE','vault-bucket-toggle','tiny',`data-index="${i}"`)}</div>`).join('')}</div>`:'<div class="empty-note mt24">Your shared list starts with one idea.</div>'}</section></div>`}

/* ───────────────────────────────── GAME LOGIC ───────────────────────────────── */
function resolveCricket(s){const c=s.worlds.cricket,role=cricketRole(c),bat=c.choices[role.batter],bowl=c.choices[role.bowler];if(!bat||!bowl)return;let off=Math.abs(bat.a-bowl.a)+Math.abs(bat.b-bowl.b);let wicket=false,runs=0;const surprise=hash(`${app.code}-${c.inning}-${c.ball}-${bat.a}${bat.b}${bat.c}${bowl.a}${bowl.b}${bowl.c}`)%5;
if(off===0){runs=bat.c===3?6:4}else if(off===1){runs=bat.c===3?4:bat.c===2?3:2}else if(off===2){if(bat.c===3&&surprise<3)wicket=true;else runs=bat.c===3?2:1}else{if(bat.c===3||surprise<2)wicket=true;else runs=0}
if(bowl.c===1&&bat.b===3&&runs>=4)runs=2;if(bowl.c===3&&bat.b===1&&bat.c===3){wicket=true;runs=0}
if(wicket)runs=0;const labels=wicket?['BOWLED! 💀','CAUGHT! 🤯','OFF STUMP GONE!'][surprise%3]:runs===6?'ABSOLUTE SIX! 🚀':runs===4?'FOURRR! 🔥':runs===0?'DOT BALL 😭':runs+' RUN'+(runs===1?'':'S')+' ✨';
c.totals[c.inning]+=runs;if(wicket)c.wickets[c.inning]++;c.history.push({inning:c.inning,ball:c.ball,runs,wicket,label:labels});c.ball++;c.choices={};if(c.ball>=6||c.wickets[c.inning]>=2){if(c.inning===0){c.inning=1;c.ball=0;log(s,'Innings break. Time to switch bats and brains.')}else{c.done=true;const k=c.totals[0],g=c.totals[1];if(k===g){award(s,'khushi',25,25,'drew the cricket cup');award(s,'gaurav',25,25,'drew the cricket cup')}else{const w=k>g?'khushi':'gaurav';award(s,w,65,55,'won the cricket cup!');award(s,other(w),10,10,'fought bravely on the pitch')}}}}
function awardQuiz(s,qid,guessKey,answer){const object=s.worlds[qid],choices=object[guessKey];if(choices.khushi===undefined||choices.gaurav===undefined)return;for(const p of ['khushi','gaurav'])if(choices[p]===answer)award(s,p,15,10,`nailed a ${qid==='jukebox'?'music':'receipts'} question`)}
async function handleAction(e){const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,index=Number(button.dataset.index),value=button.dataset.value,me=app.player,them=other(me);sfx(460);try{
 switch(action){
 case 'persona':roleChange(value);break;
 case 'login-tab':app.loginTab=value;render();break;
 case 'create':await createRoom();break;
 case 'join':await joinRoom();break;
 case 'toggle-sound':app.sound=!app.sound;render();break;
 case 'exit':if(app.unsub){app.unsub();app.unsub=null}app.localChannel?.close();app.localChannel=null;app.room=null;app.code='';app.view='lobby';sessionStorage.removeItem('usverse-last-room');render();break;
 case 'copy-code':try{await navigator.clipboard.writeText(app.code);toast('Room code copied: '+app.code)}catch(e){toast('Your code is '+app.code+' — copy it manually')}break;
 case 'home':if(app.room)await mutate(s=>{s.activeWorld='lobby'});else render();break;
 case 'open-world':if(app.room)await mutate(s=>{s.activeWorld=button.dataset.id});break;
 case 'mission-claim':await mutate(s=>{const m=s.missions[me];if(m.done)return;m.done=true;award(s,me,10,30,'completed a secret mission')});confetti();break;
 case 'mystery-start':if(!connectedOther()){toast('Your other operative needs to join first');break}await mutate(s=>{if(!s.worlds.mystery.startedAt)s.worlds.mystery.startedAt=now()});break;
 case 'mystery-submit':{const input=$('#mystery-answer'),guess=input?.value?.trim().toUpperCase().replace(/\s/g,'')||'',m=getWorld('mystery'),stage=mysteryStages[m.stage];if(guess!==stage.answer){toast('ACCESS DENIED. Wrong password. Try combining both clues.');if(input)input.value='';break}let win=false;await mutate(s=>{const w=s.worlds.mystery;if(w.completed||w.stage!==m.stage)return;award(s,'khushi',20,12,'cracked mystery file '+(w.stage+1));award(s,'gaurav',20,12);w.stage++;w.hintShown='';if(w.stage>=mysteryStages.length){w.completed=true;award(s,'khushi',75,50,'ESCAPED THE THIRD WHEEL');award(s,'gaurav',75,50);win=true}});if(win)confetti();else toast('FILE UNLOCKED. NEXT CHAMBER ACCESS GRANTED.');break}
 case 'mystery-hint':{const m=getWorld('mystery');if(app.room.state.coins[me]<15){toast('Not enough Chaos Coins');break}await mutate(s=>{if(s.coins[me]<15)return;const w=s.worlds.mystery;s.coins[me]-=15;w.hints++;w.hintShown=mysteryStages[w.stage].hint;log(s,`${nice(me)} purchased a hint for 15 coins`)});toast('HINT: '+mysteryStages[m.stage].hint);break}
 case 'mystery-deal':await mutate(s=>{const m=s.worlds.mystery,key=`${m.stage}_${me}`;if(m.deals[key])return;m.deals[key]=true;award(s,me,0,25,'took a shady side deal; both lost 60 seconds')});toast('You took the deal. The clock is NOT pleased.');break;
 case 'mystery-reset':await mutate(s=>{s.worlds.mystery=freshState().worlds.mystery;log(s,'Mystery room reset for another run')});break;
 case 'cricket-play':{const c=getWorld('cricket');if(c.done||c.choices[me])break;const data={a:Number($('#cricket-a')?.value),b:Number($('#cricket-b')?.value),c:Number($('#cricket-c')?.value)};await mutate(s=>{const c=s.worlds.cricket;if(c.done||c.choices[me])return;c.choices[me]=data;resolveCricket(s)});break}
 case 'cricket-reset':await mutate(s=>{s.worlds.cricket=freshState().worlds.cricket;log(s,'The cricket Cup starts over')});break;
 case 'mind-mode':await mutate(s=>{s.worlds.mind.mode=value});break;
 case 'mind-answer':await mutate(s=>{const m=s.worlds.mind;if(m.answers[me]===undefined&&!m.revealed)m.answers[me]=index});break;
 case 'mind-guess':await mutate(s=>{const m=s.worlds.mind;if(m.guesses[me]!==undefined||m.revealed||m.answers[me]===undefined)return;m.guesses[me]=index;if(m.guesses.khushi!==undefined&&m.guesses.gaurav!==undefined){m.revealed=true;for(const p of ['khushi','gaurav'])if(m.guesses[p]===m.answers[other(p)])award(s,p,20,10,'read their partner’s mind')}});break;
 case 'mind-next':await mutate(s=>{const m=s.worlds.mind;if(!m.revealed)return;m.idx++;m.answers={};m.guesses={};m.revealed=false});break;
 case 'mind-deep-submit':{const val=$('#deep-answer')?.value?.trim();if(!val){toast('Write your answer first.');break}await mutate(s=>{const m=s.worlds.mind;if(m.deepAnswers[me]!==undefined)return;m.deepAnswers[me]=val.slice(0,600);if(m.deepAnswers.khushi!==undefined&&m.deepAnswers.gaurav!==undefined)m.deepRevealed=true});break}
 case 'mind-deep-next':await mutate(s=>{const m=s.worlds.mind;if(!m.deepRevealed)return;m.deepIdx++;m.deepAnswers={};m.deepRevealed=false});break;
 case 'trivia-vote':await mutate(s=>{const t=s.worlds.trivia,q=triviaBank[t.idx];if(t.choices[me]!==undefined||!q)return;t.choices[me]=index;if(t.choices.khushi!==undefined&&t.choices.gaurav!==undefined)awardQuiz(s,'trivia','choices',q.type==='quote'?(q.by==='khushi'?0:1):q.answer)});break;
 case 'trivia-next':await mutate(s=>{const t=s.worlds.trivia;if(t.choices.khushi===undefined||t.choices.gaurav===undefined)return;t.idx++;t.choices={};if(t.idx>=triviaBank.length)t.done=true});break;
 case 'trivia-reset':await mutate(s=>{s.worlds.trivia=freshState().worlds.trivia});break;
 case 'art-color':app.brush=value;app.eraser=false;render();break;
 case 'art-erase':app.eraser=!app.eraser;render();break;
 case 'art-clear':if(!confirm('Clear the shared canvas for both of you?'))break;await mutate(s=>{s.worlds.art.strokes=[]});break;
 case 'art-undo':await mutate(s=>{const list=s.worlds.art.strokes;for(let i=list.length-1;i>=0;i--)if(list[i].by===me){list.splice(i,1);break}});break;
 case 'art-next':await mutate(s=>{const a=s.worlds.art;a.finished.push({prompt:artPrompts[a.idx%artPrompts.length],strokes:a.strokes.length});a.finished=a.finished.slice(-20);a.idx++;a.strokes=[];award(s,'khushi',5,5);award(s,'gaurav',5,5);log(s,'Created another questionable art masterpiece')});break;
 case 'art-save':{const canvas=$('#draw-canvas');if(!canvas)break;const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=`usverse-art-${getWorld('art').idx+1}.png`;a.click();toast('Saved your artistic crime scene');break}
 case 'hot-consent':await mutate(s=>{s.worlds.hot.consents[me]=true});break;
 case 'hot-unconsent':await mutate(s=>{s.worlds.hot.consents[me]=false});break;
 case 'hot-done':case 'hot-skip':await mutate(s=>{const h=s.worlds.hot;if(!h.consents.khushi||!h.consents.gaurav||h.done[me])return;h.done[me]=action==='hot-done'?'done':'skip';if(h.done.khushi&&h.done.gaurav){for(const p of ['khushi','gaurav'])if(h.done[p]==='done')award(s,p,0,8,`finished a Hot Mess card`);h.done={};h.idx++}});break;
 case 'casino-bet':{const bet=Number(button.dataset.bet),color=button.dataset.color;if(!Number.isFinite(bet)||!['red','black'].includes(color))break;await mutate(s=>{const c=s.worlds.casino;if(c.bets[me]||s.coins[me]<bet)return;c.bets[me]={bet,color};s.coins[me]-=bet;if(c.bets.khushi&&c.bets.gaurav){const result=hash(`${app.code}-${c.round}-${c.bets.khushi.color}-${c.bets.gaurav.color}`)%2?'red':'black';const winners=[];for(const p of ['khushi','gaurav'])if(c.bets[p].color===result){award(s,p,5,c.bets[p].bet*2,`won ${c.bets[p].bet} coins in Love Casino`);winners.push(nice(p))}const outcome={round:c.round+1,result,summary:winners.length?winners.join(' & ')+' won!':'House wins. Brutal.'};c.outcomes.push(outcome);c.outcomes=c.outcomes.slice(-20);c.last=outcome;c.round++;c.bets={}}});break}
 case 'court-submit':{const tactic=$('#court-tactic')?.value,statement=$('#court-statement')?.value?.trim();if(!statement){toast('Give your closing argument, counsel.');break}await mutate(s=>{const c=s.worlds.court;if(c.choices[me])return;c.choices[me]={tactic,statement:statement.slice(0,180)};if(c.choices.khushi&&c.choices.gaurav){const a=c.choices.khushi.tactic,b=c.choices.gaurav.tactic,winning={receipt:'alibi',alibi:'witness',witness:'receipt'};let verdict;if(a===b){verdict='A hung jury. Both somehow walk free.';award(s,'khushi',5,5);award(s,'gaurav',5,5)}else{const who=winning[a]===b?'khushi':'gaurav';verdict=`${nice(who)} wins on a technicality. Justice has left the chat.`;award(s,who,20,12,'won a ridiculous court case')}c.last={round:c.round,choices:structuredClone(c.choices),summary:verdict}}});break}
 case 'court-next':await mutate(s=>{const c=s.worlds.court;if(!c.last||c.last.round!==c.round)return;c.round++;c.choices={};c.last=null});break;
 case 'court-reset':await mutate(s=>{s.worlds.court=freshState().worlds.court});break;
 case 'jukebox-vote':await mutate(s=>{const j=s.worlds.jukebox,q=musicQs[j.idx];if(j.choices[me]!==undefined||!q)return;j.choices[me]=index;if(j.choices.khushi!==undefined&&j.choices.gaurav!==undefined)awardQuiz(s,'jukebox','choices',q.answer)});break;
 case 'jukebox-next':await mutate(s=>{const j=s.worlds.jukebox;if(j.choices.khushi===undefined||j.choices.gaurav===undefined)return;j.idx++;j.choices={};if(j.idx>=musicQs.length)j.done=true});break;
 case 'jukebox-reset':await mutate(s=>{s.worlds.jukebox=freshState().worlds.jukebox});break;
 case 'multiverse-submit':{const activity=Number($('#multi-activity')?.value),plan=$('#multi-plan')?.value?.trim()||'A surprise awaits.';await mutate(s=>{const m=s.worlds.multiverse;if(m.choices[me])return;m.choices[me]={activity,plan:plan.slice(0,190)};if(m.choices.khushi&&m.choices.gaurav){if(m.choices.khushi.activity===m.choices.gaurav.activity){award(s,'khushi',18,10,'matched date ideas');award(s,'gaurav',18,10)}}});break}
 case 'multiverse-next':await mutate(s=>{const m=s.worlds.multiverse;if(!m.choices.khushi||!m.choices.gaurav)return;m.history.push({destination:destinations[m.round%destinations.length].city,choices:structuredClone(m.choices)});m.history=m.history.slice(-10);m.round++;m.choices={}});break;
 case 'cinema-submit':{const line=$('#cinema-entry')?.value?.trim();if(!line){toast('Write something outrageous first');break}await mutate(s=>{const c=s.worlds.cinema;if(c.entries[me]||c.act>=3)return;c.entries[me]=line.slice(0,320)});break}
 case 'cinema-next':{let finished=false;await mutate(s=>{const c=s.worlds.cinema;if(!c.entries.khushi||!c.entries.gaurav)return;c.movie.push(structuredClone(c.entries));c.act++;c.entries={};if(c.act===3){finished=true;award(s,'khushi',35,20,'completed a truly questionable screenplay');award(s,'gaurav',35,20)}});if(finished)confetti();break}
 case 'cinema-reset':await mutate(s=>{s.worlds.cinema=freshState().worlds.cinema});break;
 case 'cinema-save':{const c=getWorld('cinema');const textContent=['USVERSE / OUR QUESTIONABLE BLOCKBUSTER','KHUSHI × GAURAV','',...c.movie.flatMap((scene,i)=>[`ACT ${i+1}: ${filmPrompts[i]}`,`Khushi: ${scene.khushi}`,`Gaurav: ${scene.gaurav}`,''])].join('\n');downloadText('usverse-movie.txt',textContent);break}
 case 'vault-submit':{const letter=$('#vault-letter')?.value?.trim();if(!letter){toast('Write something that matters first');break}let unlock=false;await mutate(s=>{const v=s.worlds.vault;if(v.letters[me])return;v.letters[me]=letter.slice(0,1200);if(v.letters.khushi&&v.letters.gaurav&&!v.opened){v.opened=true;unlock=true;award(s,'khushi',30,25,'unlocked the Love Vault');award(s,'gaurav',30,25)}});if(unlock)confetti();break}
 case 'vault-export':{const v=getWorld('vault');downloadText('usverse-letters.txt',`LOVE VAULT — USVERSE\n\nFrom Khushi:\n${v.letters.khushi}\n\nFrom Gaurav:\n${v.letters.gaurav}`);break}
 case 'vault-bucket':{const textVal=$('#bucket-entry')?.value?.trim();if(!textVal){toast('Add an actual dream first!');break}await mutate(s=>{const v=s.worlds.vault;if(v.bucket.length>=30)return;v.bucket.push({text:textVal.slice(0,150),by:me,done:false})});break}
 case 'vault-bucket-toggle':await mutate(s=>{const item=s.worlds.vault.bucket[index];if(item)item.done=!item.done});break;
 default:console.warn('Unknown action',action)
 }
}catch(err){console.error(err);toast('Something went wrong: '+(err.message||'Please try again'))}}
function downloadText(filename,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function tickTimers(){const el=$('[data-timer="mystery"]');if(!el||!getWorld('mystery'))return;const m=getWorld('mystery'),extra=m.hints*45000+(Object.keys(m.deals).length)*60000;el.textContent=formatTime(35*60000-(now()-m.startedAt)-extra)}
function drawStroke(ctx,s){const pts=s.points;if(!pts?.length)return;ctx.strokeStyle=s.color;ctx.lineWidth=s.size||5;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();pts.forEach(([x,y],i)=>{const px=x*ctx.canvas.width,py=y*ctx.canvas.height;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py)});if(pts.length===1){const [x,y]=pts[0];ctx.lineTo(x*ctx.canvas.width+.01,y*ctx.canvas.height+.01)}ctx.stroke()}
function paintCanvas(){const canvas=$('#draw-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.fillStyle='#f7f0ff';ctx.fillRect(0,0,canvas.width,canvas.height);const a=getWorld('art');for(const stroke of a?.strokes||[])drawStroke(ctx,stroke);if(app.stroke)drawStroke(ctx,app.stroke)}
function setupCanvas(){const canvas=$('#draw-canvas');if(!canvas)return;paintCanvas();const loc=e=>{const rect=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))]};canvas.onpointerdown=e=>{if(e.button!==0&&e.pointerType==='mouse')return;canvas.setPointerCapture(e.pointerId);app.stroke={by:app.player,color:app.eraser?'#f7f0ff':app.brush,size:app.eraser?24:app.brushSize,points:[loc(e)]};paintCanvas()};canvas.onpointermove=e=>{if(!app.stroke)return;e.preventDefault();app.stroke.points.push(loc(e));if(app.stroke.points.length>180){app.stroke.points=app.stroke.points.filter((p,i)=>i%2===0)}paintCanvas()};const end=async e=>{if(!app.stroke)return;app.stroke.points.push(loc(e));const complete=app.stroke;app.stroke=null;await mutate(s=>{const a=s.worlds.art;a.strokes.push(complete);if(a.strokes.length>220)a.strokes.shift()})};canvas.onpointerup=end;canvas.onpointercancel=end}
function levelChange(e){if(e.target.id!=='hot-level')return;const level=e.target.value;if(!['flirty','unhinged','afterdark'].includes(level))return;mutate(s=>{const h=s.worlds.hot;h.level[app.player]=level;h.consents[app.player]=false;h.done={}})}
function inputChange(e){if(e.target.id==='join-code')app.joinCode=e.target.value.toUpperCase()}
async function attemptResume(){const last=JSON.parse(sessionStorage.getItem('usverse-last-room')||'null');if(!last||last.mode!==app.mode)return;try{let room;if(app.mode==='firebase'){const snap=await app.api.get(app.api.ref(app.db,'rooms/'+last.code));room=snap.val()}else room=JSON.parse(localStorage.getItem(roomKey(last.code))||'null');if(room?.players?.[last.persona]?.uid===app.uid){await enterRoom(room,last.code,last.persona);return}}catch(err){console.warn('Resume failed',err)}sessionStorage.removeItem('usverse-last-room')}
window.addEventListener('DOMContentLoaded',async()=>{document.addEventListener('click',handleAction);document.addEventListener('change',levelChange);document.addEventListener('input',inputChange);await initFirebase();await attemptResume();render();setInterval(()=>{if(app.room?.state?.activeWorld==='mystery')tickTimers()},1000)});
